'use strict';

// Material original CEST. La pauta permanece en servidor; publicExam la retira.
const dates = ['2026-10-14','2026-10-21','2026-10-28','2026-11-04','2026-11-10'];
const exams = [];
function exam(title, review, texts) {
  const number = exams.length + 1;
  let count = 0;
  texts.forEach(text => text.questions.forEach(q => { q.id = `q${++count}`; }));
  exams.push({ number, sessionId:`sesion-u4-${number}`, date:dates[number-1], title, review, texts });
}
function text(genre, title, paragraphs, questions, table) {
  return { genre, title, paragraphs, questions, ...(table ? {table} : {}), source:'Texto original CEST, 2026. Situación ficticia para esta actividad.' };
}
function q(skill, operation, prompt, options, key, evidence, errors) {
  return { skill, operation, prompt, options, key, evidence, errors,
    demand:null };
}

exam('Decidir con evidencia', ['Narrador y perspectiva','Conflicto y motivaciones','Símbolo y sentido global','Tesis, argumentos y contraargumentos','Información explícita','Tablas y límites de una conclusión'], [
text('Cuento','La llave del taller',[
  'La primera vez que mi padre me dejó la llave del taller fue para que regara los helechos. Yo tenía dieciséis años y llevaba meses diciéndole que ya podía atender a un cliente sin que él se quedara detrás de mi hombro. Esa mañana no dijo nada sobre clientes. Puso la llave junto a mi taza y anotó en un papel: «Dos vasos por maceta; al motor azul, ni una gota». Me pareció una manera especialmente cuidadosa de seguir tratándome como un niño.',
  'El taller ocupaba una pieza al fondo de la casa. Mi padre reparaba máquinas de coser; mi abuelo había comenzado con bicicletas, y aún quedaban ruedas colgadas entre los estantes. La puerta tenía una marca donde alguna vez hubo un letrero. Mi padre no había querido reemplazarlo: los vecinos, decía, sabían llegar. Yo pensaba que un negocio sin letrero se parecía a una frase que nadie terminaba de pronunciar.',
  'En una pared había fotografías de trabajos terminados y, debajo, una repisa con piezas que todavía esperaban repuesto. Yo prefería mirar las primeras. Los objetos de la repisa me parecían fracasos que convenía esconder. Mi padre anotaba junto a cada uno el teléfono del dueño y la fecha de la última llamada. A veces pasaba más tiempo explicando por qué no podía arreglar algo que haciéndolo funcionar. Me costaba entender que una explicación también fuera parte del trabajo. Esa mañana, al quedar solo, corrí una caja para dejar más despejada la mesa.',
  'Mientras regaba, llegó una señora con una máquina envuelta en una frazada. Necesitaba terminar un uniforme para el lunes. Le expliqué que mi padre volvería en la tarde, pero ella dejó la máquina de todas maneras. «Él conoce este ruido», dijo, y me hizo escuchar el golpeteo. Cuando se fue, saqué la tapa. Había visto esa reparación muchas veces: una pieza suelta, dos tornillos, una gota de aceite. Quise que mi padre encontrara algo más que plantas mojadas.',
  'El primer tornillo salió fácilmente. El segundo se resistió y yo apreté con más fuerza. La cabeza se quebró. Me quedé sosteniendo el destornillador, como si el movimiento pudiera deshacerse si mantenía la mano en el aire. Pensé en cerrar la tapa y dejar que mi padre descubriera la falla. Incluso acomodé la frazada sobre la máquina. Entonces vi el papel junto a las macetas: dos vasos, no más; el motor, seco. La precisión que me había molestado comenzaba a tener otro sentido.',
  'Busqué una hoja del cuaderno y escribí lo ocurrido. No puse «se quebró», sino «lo quebré». Después llamé a la señora y le expliqué que la reparación tardaría más. Hubo un silencio y luego me pidió que avisara cuando supiéramos el plazo. No me felicitó por decir la verdad; tampoco reclamó. Esa falta de castigo me dejó sin la excusa que estaba preparando.',
  'Mi padre leyó la hoja al volver. Revisó la máquina, me mostró cómo sujetar la pieza y buscamos juntos el tornillo adecuado. Durante la cena preguntó cuánto dinero había en la caja. Dije que no había cobrado. Él asintió y dejó la llave al lado de mi taza otra vez. Al día siguiente regué los helechos antes de tocar cualquier herramienta. La llave pesaba lo mismo que el sábado, pero ya no me parecía una medalla.'
],[
q('LOCALIZAR','Discriminar una instrucción','¿Qué tarea le encargó inicialmente el padre al narrador?',['Cobrar una reparación pendiente.','Regar las plantas del taller.','Cambiar el tornillo de una máquina.','Llevar un uniforme a una clienta.'],'B','«fue para que regara los helechos»',['Confunde la pregunta de la cena con el encargo inicial.','Correcta.','Confunde la iniciativa del hijo con la orden del padre.','Atribuye al hijo la tarea de la clienta.']),
q('INTERPRETAR','Inferir causa y motivación desde acciones dispersas','¿Qué explica mejor que el padre vuelva a dejar la llave junto a la taza?',['Entiende que el hijo ya puede reparar cualquier máquina sin ayuda.','Busca que el hijo esconda las piezas pendientes antes de atender clientes.','Considera que el hijo merece un premio por cobrar la reparación.','Mantiene la confianza al ver que el hijo responde por el error cometido.'],'D','El hijo reconoce el error, avisa a la clienta y aprende con su padre; este vuelve a dejarle la llave sin declarar el motivo.',['Generaliza a cualquier máquina; trabajaron juntos.','El padre registra pendientes y no pide esconderlos.','No cobró y no completó solo la reparación.','Correcta: integra responsabilidad del hijo y gesto final del padre.']),
q('INTERPRETAR','Inferir una característica del personaje','¿Qué rasgo demuestra el narrador al escribir «lo quebré» y llamar a la clienta?',['Disposición a responder por sus propios errores.','Seguridad en su habilidad para reparar máquinas.','Interés en obtener un pago por cada reparación.','Desconfianza hacia la experiencia de su padre.'],'A','Escribe lo ocurrido y llama a la señora después de pensar en ocultarlo.',['Correcta.','Acaba de fallar en la reparación.','No cobra ni reclama pago.','Termina aceptando aprender del padre.']),
q('INTERPRETAR','Interpretar un símbolo','¿Qué representa la llave al final del relato?',['Una recompensa por terminar la reparación.','Un recuerdo del oficio que tenía el abuelo.','Una confianza que exige hacerse responsable.','Una señal de que el taller cambiará de dueño.'],'C','«ya no me parecía una medalla», después de asumir el error.',['No completó solo la reparación.','El abuelo aparece ligado a las ruedas.','Correcta.','No hay cambio de dueño.']),
q('INTERPRETAR','Identificar perspectiva narrativa','¿Cómo influye que el hijo relate esta historia?',['Permite conocer directamente lo que piensa la clienta.','Permite seguir cómo cambia su juicio sobre el padre.','Permite confirmar la intención del padre al dar la llave.','Permite observar los hechos sin opiniones personales.'],'B','«Me pareció… tratándome como un niño» y «comenzaba a tener otro sentido».',['No accede a pensamientos de la clienta.','Correcta.','Interpreta gestos, no conoce directamente la intención.','El relato contiene sus juicios.']),
q('REFLEXIONAR','Evaluar el efecto de un recurso','¿Qué efecto produce la repetición de la llave junto a la taza?',['Contrasta dos momentos de la relación entre padre e hijo.','Explica por qué el taller conserva herramientas antiguas.','Anticipa que la señora retirará su máquina sin pagar.','Muestra que el padre ha olvidado el encargo del sábado.'],'A','La misma ubicación abre y cierra el relato, pero cambia su sentido para el hijo.',['Correcta.','Las herramientas no explican la repetición.','No anticipa ese retiro.','El padre revisa lo sucedido.'])
]),
text('Columna de opinión','Una plaza también necesita tiempo',[
  'En la discusión sobre la remodelación de la plaza del barrio, la pregunta parece sencilla: ¿cuántos árboles caben? La propuesta municipal incluye veinte ejemplares nuevos y una zona de juegos. En los dibujos, las copas forman un techo continuo sobre los bancos. Quien mire esa imagen podría pensar que el próximo verano ya tendremos sombra. Sin embargo, los árboles del proyecto serán jóvenes y sus copas tardarán años en cubrir la superficie dibujada.',
  'Apoyo la renovación de la plaza, pero creo que el plan debería incluir sombra utilizable desde su apertura, además de árboles que crezcan. No se trata de elegir entre vegetación y estructuras livianas. Se trata de distinguir entre el beneficio futuro y una necesidad presente: niños, personas mayores y quienes esperan la micro deben poder permanecer allí mientras los árboles maduran. Una promesa de sombra no protege a alguien que espera hoy.',
  'La experiencia de la plaza del sector sur ayuda a entenderlo. El invierno pasado recibió árboles y juegos nuevos. En enero, los vecinos trasladaban sus sillas a la angosta sombra de una pared. Los bancos del centro quedaban desocupados durante la tarde. Ese ejemplo no demuestra que todas las plazas funcionen igual, pero permite anticipar un problema que el dibujo de nuestro proyecto oculta: instalar un banco y hacerlo habitable son decisiones distintas.',
  'Algunos vecinos objetan que los toldos cuestan dinero y requieren mantenimiento. La objeción es atendible: una tela rota, sin presupuesto para reemplazarla, tampoco resuelve el problema. Por eso propongo una solución temporal, de tamaño limitado, acompañada de un costo anual explícito. Si el presupuesto no alcanza para cubrir toda la plaza, se puede priorizar la zona de espera y algunos bancos. La alternativa merece compararse con otros gastos, no rechazarse por el solo hecho de necesitar cuidado.',
  'En el proyecto también aparece una franja de pavimento que facilitará el paso de coches y sillas de ruedas. Es una mejora que no conviene enfrentar con la sombra, como si reconocer una necesidad obligara a olvidar la otra. Un recorrido accesible puede terminar en un banco difícil de usar a ciertas horas. Revisar la plaza como un conjunto implica preguntar por esas relaciones. Los componentes del plano tienen presupuestos distintos, pero las personas no recorren una lista de partidas: entran, caminan, esperan y necesitan encontrar un lugar donde detenerse.',
  'También conviene escuchar a quienes usan el lugar en horarios distintos. Una visita a las nueve de la mañana no permite saber qué ocurre a las cuatro de la tarde. En una reunión, una vecina que vende pan explicó que cruza la plaza al mediodía, mientras otro vecino dijo que pasea al atardecer. Ambos describían correctamente su experiencia, aunque no estaban hablando de las mismas condiciones. Consultar a uno y tomar su respuesta como retrato de todos empobrecería la decisión.',
  'Antes de aprobar la obra, pidamos que el plano distinga la sombra prevista para el primer verano de la esperada diez años después. Pidamos también que señale quién mantendrá la solución temporal y cuándo se revisará su necesidad. Una plaza no se inaugura únicamente cuando se corta una cinta: comienza a servir cuando las personas pueden ocuparla. Plantar pensando en el futuro es valioso; planificar sin olvidar a quienes la necesitan ahora lo vuelve más justo.'
],[
q('LOCALIZAR','Ubicar un dato entre propuestas','¿Cuántos árboles nuevos incluye la propuesta municipal?',['Diez ejemplares.','Dos ejemplares.','Veinte ejemplares.','Nueve ejemplares.'],'C','«incluye veinte ejemplares nuevos»',['Confunde años de proyección con cantidad.','No corresponde al dato.','Correcta.','Confunde horario con cantidad.']),
q('INTERPRETAR','Determinar la tesis','¿Qué sostiene principalmente la autora?',['La renovación debe combinar árboles con sombra disponible al abrir.','La renovación debe esperar hasta que crezcan los árboles del sector sur.','La renovación debe concentrar sus recursos en aumentar los juegos.','La renovación debe conservar los bancos que tienen sombra al atardecer.'],'A','«el plan debería incluir sombra utilizable desde su apertura, además de árboles»',['Correcta.','No plantea postergar la obra.','No prioriza juegos.','No propone conservar esos bancos.']),
q('INTERPRETAR','Relacionar una objeción y su respuesta','¿Cómo responde la autora a la objeción sobre el mantenimiento?',['Propone que los vecinos eviten las horas de mayor calor.','Explica que los árboles nuevos no requieren cuidados.','Afirma que el costo desaparecerá después de inaugurar.','Propone una cobertura limitada con presupuesto anual definido.'],'D','«solución temporal, de tamaño limitado, acompañada de un costo anual explícito»',['No traslada la solución a horarios.','No afirma ausencia de cuidados.','Reconoce costo anual.','Correcta.']),
q('REFLEXIONAR','Evaluar la función de un ejemplo','¿Para qué se menciona la plaza del sector sur?',['Para probar que los vecinos rechazan cualquier remodelación.','Para mostrar una dificultad concreta que el nuevo plan debe prever.','Para justificar que la zona de juegos se instale junto a una pared.','Para demostrar que plantar árboles disminuye el uso de las plazas.'],'B','Los vecinos buscan sombra mientras bancos nuevos quedan desocupados.',['Exagera la reacción.','Correcta.','No propone ubicación de juegos.','Confunde falta de sombra inmediata con efecto de plantar.']),
q('INTERPRETAR','Interpretar una expresión en contexto','¿Qué significa «una promesa de sombra no protege a alguien que espera hoy»?',['El dibujo del proyecto debe eliminar las copas de los árboles.','La plaza tiene usuarios que prefieren las estructuras a los árboles.','Un beneficio futuro no resuelve por sí mismo una necesidad actual.','Los árboles jóvenes dejan de crecer cuando hay toldos cercanos.'],'C','Contrasta copas futuras con uso presente de la plaza.',['No exige eliminar el dibujo, sino distinguir plazos.','No refiere a preferencias personales.','Correcta.','Introduce una relación biológica ausente.']),
q('REFLEXIONAR','Identificar una falla de argumentación','¿Qué error habría en describir a todos los usuarios a partir de una visita a las nueve?',['Usar una observación limitada para concluir sobre otras condiciones.','Comparar el mantenimiento de una tela con el de una zona de juegos.','Distinguir la sombra disponible hoy de la que habrá en diez años.','Considerar el testimonio de quienes pasan al mediodía y al atardecer.'],'A','«Una visita a las nueve… no permite saber qué ocurre a las cuatro».',['Correcta.','No es la generalización descrita.','Es una distinción válida.','Amplía las perspectivas.'])
]),
text('Informe con tabla','Biblioteca abierta: visitas y préstamos',[
  'La biblioteca del barrio probó durante abril tres horarios de apertura. En la primera semana abrió de 9:00 a 13:00; en la segunda, de 13:00 a 17:00; en la tercera, de 17:00 a 21:00. Cada prueba duró cinco días. El equipo contó las visitas y los préstamos de libros en cada horario. Una visita no equivale a un préstamo: una persona puede leer allí, pedir ayuda o devolver un libro sin llevarse otro.',
  'El informe reúne los registros en la tabla. Las cifras corresponden a entradas, no a personas distintas: alguien que fue dos días aparece dos veces. Además, las semanas no tuvieron las mismas actividades. Durante la tercera se realizó una muestra de fotografías, mientras en la primera hubo un taller para niñas y niños. No se registró si cada visitante participaba en esas actividades.',
  'El equipo propone mantener temporalmente dos tardes de apertura y observar el uso durante un mes sin eventos especiales. Antes de decidir un cambio permanente, consultará también a quienes no pudieron asistir a ninguno de los horarios. El informe no recomienda cerrar por las mañanas: señala que contar las visitas ayuda a decidir, pero no reemplaza la pregunta sobre las necesidades de cada grupo.'
],[
q('LOCALIZAR','Leer una fila de una tabla','¿En qué horario se registraron 48 préstamos?',['De 9:00 a 13:00.','De 13:00 a 17:00.','De 17:00 a 21:00.','Durante todo el mes.'],'B','Fila de 13:00 a 17:00: 48 préstamos.',['Confunde 42 con 48.','Correcta.','Confunde 45 con 48.','El dato corresponde a una semana.']),
q('LOCALIZAR','Discriminar dos columnas','¿Qué horario tuvo más visitas registradas?',['De 13:00 a 17:00, con 48.','De 9:00 a 13:00, con 60.','De 13:00 a 17:00, con 80.','De 17:00 a 21:00, con 90.'],'D','La columna visitas registra 60, 80 y 90.',['Lee préstamos en vez de visitas.','Elige la primera fila.','No es el máximo.','Correcta.']),
q('INTERPRETAR','Integrar texto y tabla','¿Por qué las 90 visitas de la tercera semana no indican 90 lectores distintos?',['El registro cuenta entradas y una persona puede volver.','El registro incluye únicamente quienes pidieron préstamos.','El registro considera solo visitas a la muestra de fotos.','El registro suma las personas de las tres semanas.'],'A','«entradas, no… personas distintas»',['Correcta.','El texto distingue visitas y préstamos.','No se registró participación en eventos.','Cada fila corresponde a su semana.']),
q('INTERPRETAR','Inferir el propósito de un procedimiento','¿Para qué se propone observar un mes sin eventos especiales?',['Para dejar de registrar los préstamos de la biblioteca.','Para comparar el tamaño de los talleres con las exposiciones.','Para conocer el uso del horario con menos factores adicionales.','Para asegurar que las mismas personas visiten cada semana.'],'C','Las semanas tuvieron actividades distintas; se propone observar sin eventos.',['Se mantiene evaluación.','No compara tamaños.','Correcta.','No controla identidad de asistentes.']),
q('REFLEXIONAR','Evaluar suficiencia de evidencia','¿Qué conclusión está mejor respaldada por el informe?',['La muestra de fotografías explica por sí sola el aumento de visitas.','La tercera semana tuvo más entradas, sin probar preferencia general.','El horario matinal debe cerrarse porque resulta innecesario al barrio.','Las personas del barrio prefieren pedir libros después de las cinco.'],'B','Hay más entradas en la tercera fila, pero eventos y usuarios no son controlados.',['No se identificó participación.','Correcta.','El informe no recomienda cerrarlo.','No se midieron preferencias; préstamos no son el máximo.']),
q('REFLEXIONAR','Determinar la función de un recurso no lingüístico','¿Qué aporta la tabla a la lectura del informe?',['Identifica los motivos personales de cada visitante.','Demuestra qué actividad atrajo a cada grupo del barrio.','Explica por qué algunas personas no pudieron asistir.','Permite contrastar visitas y préstamos en cada horario.'],'D','Presenta dos conteos por cada horario de apertura.',['No recoge motivos.','No vincula entradas con actividad.','No consulta ausentes todavía.','Correcta.'])
],{headers:['Horario probado','Visitas registradas','Préstamos'],rows:[['9:00–13:00','60','42'],['13:00–17:00','80','48'],['17:00–21:00','90','45']],caption:'Registro de cinco días por horario. Datos ficticios para lectura.'})
]);

exam('Voces, imágenes y memoria', ['Hablante lírico y temple de ánimo','Lenguaje figurado y repetición','Noticia: hecho y opinión','Crónica y perspectiva','Causa y consecuencia','Propósito de testimonios'], [
text('Poema','Casa en tránsito',[
 'Mi madre dobla el mantel\ncomo quien dobla una tarde.\nQueda en la tela una sombra\nde vasos que nadie trae.\nLa mesa ya está desnuda,\nla casa empieza a mudarse.',
 'En una caja sin nombre\nguardo el ruido de la llave,\nel peldaño que protesta,\nla ventana de la calle.\nNo caben dentro los ruidos:\ncierran la tapa y se salen.',
 'Mi hermano mide la puerta\npara que el sofá no se trabe.\nYo mido el último invierno\nen la marca de un ventanal.\nÉl dice: «Todo se lleva».\nYo sé que algo va a quedarse.',
 'Queda la luz de las cinco,\nqueda el olor de las tardes,\nqueda la voz que nos llama\ndesde un patio que no cabe.\n¿Quién podrá cargar un patio\nsin que se pierda su aire?',
 'En la otra casa habrá un árbol,\nuna mesa y otras llaves.\nQuizás la primera noche\nnos cueste encontrar el sueño.\nQuizás la mañana siguiente\nabra una puerta en lo nuevo.',
 'Mi madre dobla el mantel,\nmi hermano sostiene el marco.\nYo levanto una caja vacía\nque, sin embargo, pesa.\nSalimos: la calle de siempre\nnos devuelve otros pasos.'
],[
q('LOCALIZAR','Ubicar una acción explícita','¿Qué hace el hermano para facilitar la mudanza?',['Dobla el mantel sobre la mesa.','Guarda las llaves en una caja.','Mide la puerta para pasar el sofá.','Busca un árbol para la casa nueva.'],'C','«Mi hermano mide la puerta / para que el sofá no se trabe».',['Es acción de la madre.','El hablante guarda el ruido, no llaves.','Correcta.','La otra casa ya tendrá un árbol.']),
q('INTERPRETAR','Interpretar lenguaje figurado','¿Qué sugiere la caja vacía que «sin embargo, pesa»?',['El esfuerzo necesario para cargar el sofá.','La carga emocional de abandonar la casa.','El tamaño de los objetos que faltan guardar.','La dificultad de cerrar una caja defectuosa.'],'B','La caja vacía se vincula con ruidos y recuerdos que no pueden guardarse.',['Cambia el referente.','Correcta.','Está vacía, no llena de objetos.','No se describe un defecto.']),
q('INTERPRETAR','Determinar temple de ánimo','¿Qué combinación describe mejor el ánimo del hablante?',['Orgullo por el pasado e indiferencia hacia el futuro.','Enojo con su familia y satisfacción por marcharse.','Temor a la calle y confianza en conservar cada objeto.','Nostalgia por la casa y apertura incierta a lo nuevo.'],'D','Contrasta «algo va a quedarse» con «Quizás… abra una puerta en lo nuevo».',['El futuro le importa.','No hay conflicto con la familia.','No teme la calle ni preserva todo.','Correcta.']),
q('INTERPRETAR','Integrar el contraste de voces','¿Qué diferencia hay entre las miradas del hermano y del hablante?',['Uno piensa en trasladar objetos; el otro, en lo que no se puede trasladar.','Uno quiere quedarse en la casa; el otro, salir hacia la casa nueva.','Uno recuerda la infancia; el otro, organiza únicamente los muebles.','Uno desconoce el destino; el otro, conoce a los nuevos vecinos.'],'A','El hermano mide el sofá y dice «Todo se lleva»; el hablante piensa en recuerdos.',['Correcta.','Ambos participan de la mudanza.','Invierte el contraste.','No se menciona a vecinos.']),
q('INTERPRETAR','Determinar el sentido global','¿Cuál es el tema central del poema?',['La rivalidad familiar que provoca el reparto de los muebles.','El desgaste de una vivienda abandonada durante el invierno.','La experiencia de dejar un lugar que conserva recuerdos.','La búsqueda de una casa con más espacio para sus objetos.'],'C','La mudanza atraviesa estrofas materiales y emocionales.',['No hay disputa por muebles.','La casa no estaba abandonada.','Correcta.','El espacio no motiva la mudanza.']),
q('REFLEXIONAR','Evaluar la repetición','¿Qué efecto tiene repetir «queda» en la cuarta estrofa?',['Precisa una lista de muebles que se entregarán a otra familia.','Destaca la persistencia de experiencias que no se pueden empacar.','Explica el orden en que los familiares salen de la casa.','Resuelve la duda sobre cuánto mide el sofá de la familia.'],'B','Reitera luz, olor y voz: experiencias asociadas a la casa.',['Son experiencias, no muebles.','Correcta.','No organiza la salida.','No explica medidas.'])
]),
text('Noticia','Un archivo que vuelve a escucharse',[
 'El centro cultural de Puerto Claro abrió el martes una colección digital con cincuenta entrevistas a antiguos trabajadores del puerto. Las grabaciones se realizaron entre 1986 y 1989 y habían permanecido en cintas guardadas en un armario. La consulta de los audios será gratuita; los originales quedarán bajo resguardo del centro. El proyecto comenzó hace seis meses, después de que una vecina entregara un inventario de las cintas.',
 'La encargada del archivo, Elisa Rojas, explicó que digitalizar no consistió únicamente en copiar el sonido. Primero se revisó el estado de las cintas y luego se identificaron fechas, participantes y lugares. En algunos casos faltaba esa información. El equipo contrastó las voces con documentos y consultó a familiares para evitar atribuir una entrevista a la persona equivocada. Los audios con identidad todavía dudosa permanecerán fuera del catálogo público.',
 'Una de las dificultades fue el deterioro de doce cintas. Según Rojas, se pudo recuperar el sonido de nueve de ellas; las otras tres siguen en revisión. La colección publicada incluye únicamente entrevistas cuya identificación y reproducción pudieron verificarse. «Preferimos reconocer un vacío antes que llenarlo con una suposición», señaló. El inventario original reunía más registros que los disponibles en esta primera apertura.',
 'Los primeros archivos de prueba se escucharon en dos equipos distintos. Una grabación que parecía clara con audífonos resultaba difícil de entender en los parlantes de la sala. El equipo decidió mantener el audio y añadir una advertencia sobre su calidad, en vez de completar palabras dudosas. En las fichas se distingue entre la voz de la persona entrevistada y las notas incorporadas durante la revisión. Rojas informó que algunos visitantes podrán aportar antecedentes, pero que el catálogo no presentará una explicación reciente como si hubiera sido dicha en la entrevista original.',
 'El centro preparó además una muestra con fotografías del mismo período. Las imágenes no pertenecen necesariamente a los episodios descritos en los audios. Por esa razón se exhiben en una sección separada, con su fecha y procedencia. La encargada señaló que reunir materiales puede ayudar a conocer una época, aunque también puede crear asociaciones engañosas si se hace creer que una fotografía registra un hecho del que solo se conserva un relato.',
 'Durante la presentación, el antiguo estibador Raúl Campos escuchó un fragmento en el que su padre describía una jornada de descarga. Campos dijo que nunca había oído esa grabación y que reconoció la voz por una forma particular de terminar las frases. «En la casa hablaba poco del puerto; aquí pude escuchar la parte que no conocíamos», comentó. Su testimonio fue uno de los tres presentados al público durante la ceremonia.',
 'La agrupación de vecinos pidió que el catálogo permita añadir correcciones. El centro anunció que habilitará un formulario, pero aclaró que los cambios se incorporarán después de revisar su respaldo. Una identificación propuesta por un visitante no reemplazará automáticamente la ficha existente. El sitio mostrará tanto la fecha de grabación como la fecha de la última revisión de cada registro.',
 'Elisa Rojas considera que la colección es «una puerta para conocer la vida cotidiana del puerto». Esa valoración no equivale a afirmar que todas las experiencias de sus trabajadores estén representadas: las entrevistas provienen de un proyecto acotado y algunas voces no fueron grabadas. El centro invitó a escuelas y organizaciones a consultar el archivo y anunció una segunda apertura cuando termine la revisión de los materiales pendientes.'
],[
q('LOCALIZAR','Discriminar fechas','¿Cuándo se realizaron las entrevistas de la colección?',['Entre 1986 y 1989.','Durante los últimos seis meses.','El martes de la inauguración.','Después de la segunda apertura.'],'A','«Las grabaciones se realizaron entre 1986 y 1989».',['Correcta.','Es la duración del proyecto digital.','Es la fecha de apertura.','Es una actividad futura.']),
q('INTERPRETAR','Inferir una causa','¿Por qué algunos audios todavía no se publican?',['Porque el centro cobrará por escuchar los originales.','Porque contienen opiniones contrarias a las del equipo.','Porque los vecinos solicitaron retirar toda la colección.','Porque su identidad o su reproducción aún requieren verificación.'],'D','Identidad dudosa fuera del catálogo y tres cintas aún en revisión.',['La consulta es gratuita.','No se censuran opiniones.','Pidieron correcciones, no retiro.','Correcta.']),
q('INTERPRETAR','Relacionar una cita con el procedimiento','¿Qué expresa Rojas al preferir «reconocer un vacío»?',['Que la colección ha perdido su valor histórico.','Que una información incompleta debe completarse con recuerdos.','Que la falta de certeza debe hacerse visible antes que inventarse.','Que los documentos escritos pueden reemplazar los audios faltantes.'],'C','«antes que llenarlo con una suposición» y validación previa de identidad.',['No niega su valor.','Justamente rechaza una suposición.','Correcta.','No propone sustitución de materiales.']),
q('REFLEXIONAR','Determinar función de un testimonio','¿Qué aporta el testimonio de Raúl Campos a la noticia?',['Prueba que todas las identidades del catálogo son correctas.','Muestra un efecto personal de recuperar una voz del archivo.','Establece la fecha exacta en que se hicieron las entrevistas.','Demuestra que el padre dirigió el proyecto de digitalización.'],'B','Reconoce la voz de su padre y conoce una parte de su experiencia.',['Un testimonio no verifica todo.','Correcta.','No aporta fecha exacta.','El padre es entrevistado, no director.']),
q('INTERPRETAR','Distinguir hecho y valoración','¿Cuál de estos enunciados corresponde a una valoración citada?',['La consulta de los audios será gratuita.','El centro abrió cincuenta entrevistas digitales.','Tres cintas deterioradas siguen en revisión.','La colección es una puerta a la vida del puerto.'],'D','Rojas «considera» que es «una puerta…».',['Condición de acceso anunciada.','Dato de apertura.','Dato del proceso.','Correcta.']),
q('REFLEXIONAR','Evaluar un titular según el alcance de la evidencia','¿Qué titular representa mejor el contenido de la noticia?',['Recuperan y publican parte de las voces históricas del puerto.','Todos los trabajadores del puerto ya tienen su historia en línea.','Vecinos reemplazan las fichas del archivo por recuerdos familiares.','Centro cultural recupera la totalidad de sus cintas deterioradas.'],'A','Primera apertura acotada, pendientes y límites de representación.',['Correcta.','Generaliza más allá del proyecto.','Las correcciones deben revisarse.','Quedan tres cintas pendientes.'])
]),
text('Crónica','El último viaje de la tarde',[
 'Subí al bus de las seis con la libreta abierta. Me habían encargado escribir sobre la suspensión del recorrido que unía el pueblo con la estación. Imaginaba una despedida solemne: vecinos en la plaza, un discurso, alguna cinta. Encontré a cuatro pasajeros y al conductor revisando una rueda. Nadie llevaba flores. Una mujer preguntó si habría vuelto del terminal la encomienda que esperaba desde el lunes.',
 'El conductor arrancó siete minutos después de la hora. La señora de la encomienda se sentó delante; un estudiante abrió sus apuntes; los otros dos pasajeros conversaron sobre la lluvia. Yo anoté «indiferencia», aunque la palabra empezó a incomodarme antes de terminarla. En la tercera parada subió un hombre con una caja de herramientas. El conductor lo llamó por su nombre y le preguntó si había arreglado la bomba de agua de su madre.',
 'El paisaje avanzaba detrás del vidrio: cercos torcidos, huertas pequeñas, una cancha donde alguien recogía los arcos. El estudiante cerró sus apuntes al pasar por su antigua escuela. «Aquí subía mi abuelo», dijo, sin mirar a nadie en particular. La mujer de delante respondió que él siempre esperaba bajo el árbol para no mojar el asiento con el paraguas. Durante algunos kilómetros, el bus estuvo lleno de personas que no estaban allí.',
 'Al detenernos junto a un almacén, el conductor bajó una bolsa pequeña y la dejó sobre el mostrador. La dueña salió a saludarlo. Pensé que el encargo retrasaría el viaje, pero volvimos a partir antes de que yo terminara de buscar el reloj. La mujer de delante explicó que aquel intercambio se repetía cada jueves. No anoté su contenido: nadie lo había ofrecido para mi libreta. Escribí solamente que el recorrido tenía paradas que no figuraban en el cartel del terminal. Una ruta puede caber en un dibujo sin que en él quepa todo lo que las personas hacen al recorrerla.',
 'Pregunté al conductor qué haría el lunes. Dijo que le habían ofrecido otro trayecto, pero aún no sabía si lo aceptaría. Después señaló una curva: de niño, aseguró, podía anticiparla dormido por el ruido del motor. No insistí en mi pregunta. Miré la línea que había escrito: «indiferencia». La taché. El silencio de una persona no tiene necesariamente el mismo significado que el silencio de una máquina.',
 'En la estación no hubo discurso. El conductor ayudó a bajar la caja de herramientas y recibió una bolsa de naranjas de la mujer de delante. Ella había recogido su encomienda en una parada intermedia. «Para el viaje de vuelta», explicó. El estudiante pidió fotografiar el bus. Yo guardé la libreta antes de que se juntaran frente a la puerta. Me ofrecieron salir en la imagen, pero preferí sostener el teléfono.',
 'Volví caminando con el estudiante. Me dijo que el lunes tendría que salir media hora antes para alcanzar otro recorrido. Lo anoté al llegar a casa. Mi crónica ya no comenzaría con una ceremonia que no había ocurrido. Comenzaría con la rueda revisada, con la bolsa de naranjas y con esa media hora. A veces un cambio parece pequeño desde una plaza; en el horario de una persona ocupa un lugar mucho mayor.'
],[
q('LOCALIZAR','Ubicar una consecuencia explícita','¿Qué cambio enfrentará el estudiante el lunes?',['Deberá llevar una encomienda a la estación.','Deberá salir media hora antes para tomar otro recorrido.','Deberá trabajar en la reparación de la bomba de agua.','Deberá caminar hasta su antigua escuela antes de viajar.'],'B','«tendría que salir media hora antes para alcanzar otro recorrido».',['Espera de otra pasajera.','Correcta.','Trabajo del hombre de herramientas.','La antigua escuela es un recuerdo.']),
q('LOCALIZAR','Discriminar participantes','¿Quién entrega una bolsa de naranjas al conductor?',['El estudiante que fotografía el bus.','El hombre con la caja de herramientas.','La persona que escribe la crónica.','La mujer que esperaba una encomienda.'],'D','«recibió una bolsa de naranjas de la mujer de delante».',['Confunde fotografía con regalo.','Confunde ayuda con regalo.','Sostiene el teléfono.','Correcta.']),
q('INTERPRETAR','Inferir el cambio de perspectiva','¿Por qué la narradora tacha «indiferencia»?',['Comprende que los gestos cotidianos también expresan vínculos.','Descubre que los pasajeros desconocían la suspensión del recorrido.','Confirma que el conductor prepara una ceremonia en la estación.','Comprueba que el viaje tiene pocos pasajeros por culpa de la lluvia.'],'A','Recuerdos del abuelo, del conductor y gestos sin ceremonia.',['Correcta.','No se afirma que lo ignoren.','No hay ceremonia.','No explica asistencia por lluvia.']),
q('INTERPRETAR','Interpretar una imagen','¿Qué sugiere que el bus se llene de personas «que no estaban allí»?',['Que otros pasajeros subieron sin ser vistos por la narradora.','Que el recorrido había recogido a vecinos en paradas anteriores.','Que los recuerdos hacen presentes a antiguos pasajeros.','Que los asientos conservan objetos de viajeros ausentes.'],'C','Se habla del abuelo y de su forma de esperar bajo el árbol.',['Literaliza la imagen.','No refiere a un aumento de pasajeros.','Correcta.','No se describen esos objetos.']),
q('REFLEXIONAR','Evaluar el efecto del cierre','¿Qué aporta la «media hora» al cierre de la crónica?',['Permite establecer cuánto se retrasó el conductor durante el viaje.','Demuestra que el nuevo recorrido será más lento que el anterior.','Explica por qué la narradora rechazó aparecer en la fotografía.','Concreta el efecto de la suspensión en la vida de un pasajero.'],'D','El estudiante deberá reorganizar su salida a partir del lunes.',['El retraso fue siete minutos.','No se mide duración del recorrido.','No explica esa decisión.','Correcta.']),
q('REFLEXIONAR','Evaluar la representación de una experiencia','¿Qué decisión fortalece la fidelidad de esta crónica?',['Sustituir los hechos por la ceremonia imaginada al subir al bus.','Revisar la impresión inicial al contrastarla con lo observado.','Eliminar los recuerdos porque los ausentes no viajaron ese día.','Describir el silencio como una señal común de todos los pasajeros.'],'B','La narradora corrige «indiferencia» y abandona la ceremonia inexistente.',['Inventaría un hecho.','Correcta.','Los recuerdos sí son parte de la experiencia.','Generaliza una interpretación descartada.'])
])
]);

exam('Conflictos y decisiones públicas', ['Conflicto dramático','Diálogo y acotaciones','Estereotipos y prejuicios','Reportaje y fuentes','Discurso y destinatario','Recursos persuasivos'], [
text('Escena dramática','La banca del andén',[
 'Personajes: INÉS, encargada de la estación; TOMÁS, estudiante; JULIA, antigua usuaria.\n(Una banca de madera está junto al andén. Inés pega un cartel: «Retiro de mobiliario, viernes». Tomás sostiene una carpeta. Julia limpia con un pañuelo un extremo de la banca.)',
 'TOMÁS: Traje las firmas. Ciento veinte personas quieren conservarla.\nINÉS: Las recibo, pero una firma no repara una pata suelta. El informe dice que la banca puede volcarse.\nJULIA: Esa pata lleva años así. Mi marido la afirmaba con una piedra.\nINÉS: Justamente por eso pedí la revisión. No puedo esperar a que alguien se caiga.\nTOMÁS: Entonces repárela.\nINÉS: El presupuesto alcanza para retirar la banca y poner tres asientos nuevos. Repararla cuesta más.',
 'JULIA: Los asientos nuevos no tendrán lugar para esperar juntos.\nINÉS: Tendrán respaldo y una base firme.\nJULIA: No estoy pidiendo que se sienten sobre un recuerdo. Estoy diciendo que en esa banca cabían mi marido, las bolsas y el nieto.\n(Tomás abre la carpeta, busca una hoja y vuelve a cerrarla.)\nTOMÁS: Podríamos reunir lo que falta.\nINÉS: ¿Quién certificará la reparación? ¿Quién responde si vuelve a fallar?',
 'TOMÁS: Un exalumno trabaja con madera. Dijo que podía ayudarnos.\nINÉS: ¿La vio o habló después de mirar una foto?\nTOMÁS: Le mandé una foto.\nINÉS: Desde ahí no puede saber qué ocurre bajo el asiento.\nJULIA: Tampoco el informe cuenta por qué nos reunimos aquí.\nINÉS: No se lo pedimos. Le pedimos revisar la estructura. Podemos juntar las dos cosas sin pedirle a una que responda por la otra.\n(Tomás mira por debajo de la banca. Julia le sostiene la carpeta.)\nTOMÁS: Nunca había visto esa unión. En las fotos sale siempre el respaldo.\nJULIA: Es el lado desde el que nos sentábamos.\nINÉS: Y para arreglarla habrá que mirar también desde donde nadie posa.',
 'TOMÁS: Siempre hay un papel que impide hacer algo.\nINÉS: El mismo papel que mañana usarías para preguntar por qué no protegimos a los pasajeros.\nJULIA: Él cree que ustedes quieren borrar el pasado. Usted cree que él quiere sentarnos en una trampa. Estamos hablando como si solo hubiera esas dos opciones.\n(Se oye un tren a lo lejos. Inés mira el reloj, pero no recoge las firmas.)',
 'INÉS: El carpintero ofreció revisar la estructura el jueves. Si es reparable y conseguimos el dinero, podemos estudiar una alternativa. Hasta entonces nadie se sienta.\nTOMÁS: ¿Y el viernes?\nINÉS: El retiro sigue programado. Puedo pedir que esperen el informe, no prometer que lo autoricen.\nJULIA: Yo tengo una foto del andén cuando lo inauguraron. Se ve la banca. Quizás sirva para entender por qué nos importa.\nINÉS: Tráigala. Junto al informe, no en su lugar.',
 '(Tomás deja las firmas sobre la banca y las retira enseguida. Julia guarda el pañuelo. Inés pega otro cartel: «No utilizar hasta nueva revisión». Los tres permanecen de pie.)\nTOMÁS: ¿Nos juntamos el jueves?\nINÉS: Después de la revisión. Con una cifra y un responsable.\nJULIA: Y con la foto.\n(La luz se apaga mientras Tomás anota la hora en la carpeta.)'
],[
q('LOCALIZAR','Discriminar una fecha','¿Cuándo está programada la revisión del carpintero?',['El viernes del retiro.','El día de la inauguración.','El jueves anterior al retiro.','Después de instalar los asientos.'],'C','«El carpintero ofreció revisar la estructura el jueves».',['Confunde revisión y retiro.','Es el momento de la foto.','Correcta.','No se condiciona a instalar asientos.']),
q('INTERPRETAR','Determinar el conflicto','¿Qué conflicto organiza la escena?',['Conservar una banca significativa sin comprometer la seguridad.','Repartir las firmas entre quienes esperan en la estación.','Decidir quién heredará la fotografía del antiguo andén.','Averiguar quién dejó una piedra bajo la banca de madera.'],'A','Se enfrenta memoria/uso comunitario con riesgo, costo y responsabilidad.',['Correcta.','Las firmas apoyan una petición.','No se discute herencia.','La piedra es un antecedente, no el conflicto central.']),
q('INTERPRETAR','Inferir motivaciones','¿Por qué Julia menciona las bolsas y el nieto?',['Para explicar quién dañó la pata de la banca.','Para pedir asientos reservados para su familia.','Para demostrar que su marido reparaba muebles.','Para mostrar una forma de uso que los asientos separados perderían.'],'D','«en esa banca cabían mi marido, las bolsas y el nieto».',['No identifica causante.','No pide privilegio familiar.','No habla de su oficio.','Correcta.']),
q('INTERPRETAR','Relacionar un cambio de actitud','¿Qué cambio se produce en Tomás al final?',['Abandona la petición porque deja de valorar la banca.','Acepta discutir condiciones concretas además de reunir firmas.','Decide usar la banca mientras espera el informe del carpintero.','Pide retirar la banca antes de que los vecinos vean la fotografía.'],'B','Anota una reunión con cifra y responsable; retira las firmas de la banca.',['Continúa participando.','Correcta.','No se sienta; retira papeles.','No pide retiro anticipado.']),
q('INTERPRETAR','Interpretar una relación entre ideas','¿Qué quiere decir Inés con «Junto al informe, no en su lugar»?',['La foto debe ocultarse para evitar una discusión entre vecinos.','La foto permitirá calcular por sí sola el costo de la reparación.','La memoria importa, pero no reemplaza la revisión de seguridad.','La revisión quedará cancelada cuando se encuentre la foto original.'],'C','Acepta la foto y mantiene el informe, la cifra y el responsable.',['La recibe.','No aporta costo.','Correcta.','No cancela la revisión.']),
q('REFLEXIONAR','Evaluar la función de una acotación','¿Qué aporta la acotación final que deja a los tres de pie?',['Hace visible que buscan una salida sin usar todavía la banca.','Confirma que han decidido cambiar la banca por asientos nuevos.','Muestra que Tomás rechaza volver a reunirse con la encargada.','Demuestra que la fotografía ya resolvió el problema de seguridad.'],'A','Cartel de no utilizar; todos de pie, reunión pendiente.',['Correcta.','La decisión está abierta.','Acuerda volver.','La foto no se ha traído.'])
]),
text('Reportaje','Reparar antes de reemplazar',[
 'En la sala de la junta vecinal de Las Lomas hay una fila de objetos: una radio, dos lámparas y una mochila con el cierre roto. No es una feria de ventas. Una vez al mes, personas con distintos oficios ayudan a revisar aparatos y a enseñar reparaciones sencillas. La iniciativa comenzó con cuatro voluntarios; hoy participa un grupo de doce. Cada objeto recibe una ficha, aunque no todos salen funcionando.',
 'La coordinadora, Paula Vidal, distingue entre reparar y prometer. Antes de conectar un aparato, el equipo revisa su estado y pregunta por la falla. Los trabajos que requieren piezas inaccesibles o representan un riesgo se derivan a un servicio especializado. «No basta con que encienda una vez», explica. Según su registro del último encuentro, se recibieron treinta objetos: dieciocho pudieron repararse, siete quedaron pendientes y cinco fueron derivados.',
 'Una lámpara ilustra la diferencia. Su dueña pensaba que había que cambiar la ampolleta, pero la revisión encontró un cable dañado. El voluntario no la encendió para comprobar la hipótesis inicial. Primero aisló la falla y explicó por qué el arreglo debía esperar. La dueña se fue sin la lámpara encendida, pero con una ficha que indicaba qué pieza comprar y dónde consultar. En el conteo aparece como pendiente, no como reparación terminada.',
 'La iniciativa también intenta que el conocimiento no se quede en manos de una sola persona. Quien trae un objeto puede observar el procedimiento cuando es seguro y preguntar por el cuidado posterior. Un estudiante aprendió a coser el tirante de su mochila y luego mostró el punto a un vecino. Vidal considera ese intercambio un resultado del encuentro, aunque reconoce que todavía no tienen un registro que permita medir cuánto aprenden los asistentes.',
 'En una mesa cercana, una voluntaria muestra fotografías de un arreglo anterior. La secuencia no termina en la imagen del objeto funcionando: incluye una nota sobre su revisión después de dos semanas. Vidal explica que ese seguimiento les permite corregir una impresión inicial. Algo puede parecer resuelto durante el encuentro y volver a fallar al usarlo en la casa. El grupo todavía recibe pocas respuestas a esa consulta, de modo que no presenta la duración de las reparaciones como un resultado conocido para todos los casos. Quieren mejorar el seguimiento antes de ampliar la cantidad de objetos que reciben.',
 'El técnico Ernesto Soto cuestiona que cualquier aparato se repare en una reunión abierta. Señala que intervenir una batería o una instalación eléctrica exige formación y herramientas apropiadas. La coordinadora coincide en ese límite y muestra el protocolo de derivación. Para Soto, la iniciativa resulta útil si ayuda a distinguir una reparación accesible de un trabajo que requiere un especialista. Su observación modifica la idea de que reparar siempre es la mejor decisión inmediata.',
 'El municipio estudia facilitar una sala permanente, pero aún no ha aprobado recursos. Mientras tanto, los voluntarios conservan las fichas y consultan al mes siguiente por los objetos pendientes. El número de reparaciones informa una parte de la experiencia; el registro de derivaciones permite conocer otra. La historia de una lámpara que vuelve a encenderse es fácil de contar. La de una lámpara que conviene no encender todavía también explica lo que este espacio busca hacer.'
],[
q('LOCALIZAR','Ubicar datos de un registro','¿Cuántos objetos quedaron pendientes en el último encuentro?',['Cinco objetos.','Doce objetos.','Dieciocho objetos.','Siete objetos.'],'D','Registro: 18 reparados, 7 pendientes, 5 derivados.',['Son derivados.','Son voluntarios.','Son reparados.','Correcta.']),
q('INTERPRETAR','Determinar sentido global','¿Cuál es la idea central del reportaje?',['Los encuentros reemplazan los servicios de reparación especializada.','La reparación comunitaria combina ayuda, aprendizaje y límites de seguridad.','Los voluntarios buscan vender aparatos que ya no usan los vecinos.','La iniciativa mide con precisión cuánto aprende cada asistente.'],'B','Fichas, aprendizaje con límites y derivación a especialistas.',['Los derivan.','Correcta.','No es feria de ventas.','Reconoce que falta ese registro.']),
q('INTERPRETAR','Inferir una causa','¿Por qué la lámpara se registra como pendiente?',['Su dueña no aceptó que revisaran el cable dañado.','El voluntario decidió cambiar una ampolleta que funcionaba.','Faltaba resolver una falla antes de volver a encenderla con seguridad.','La junta vecinal no tenía autorización para registrar lámparas.'],'C','Cable dañado, pieza por comprar y consulta pendiente.',['Acepta la ficha.','No cambia ampolleta.','Correcta.','Sí se registra.']),
q('REFLEXIONAR','Determinar función de una fuente','¿Qué aporta la opinión de Ernesto Soto?',['Introduce un límite técnico que ayuda a evaluar la iniciativa.','Demuestra que los treinta objetos fueron atendidos de manera incorrecta.','Confirma que el municipio ya financió una sala permanente.','Sustituye el registro de fichas por la historia de un participante.'],'A','Exige formación en baterías/electricidad y valora distinguir/derivar.',['Correcta.','No evalúa todos como incorrectos.','No habla de financiación aprobada.','Complementa el registro.']),
q('INTERPRETAR','Distinguir evidencia y alcance','¿Qué resultado todavía no puede cuantificar el equipo?',['La cantidad de objetos recibidos en la reunión.','La cantidad de aparatos enviados a especialistas.','La cantidad de personas voluntarias que participan.','La cantidad de aprendizaje alcanzada por los asistentes.'],'D','«todavía no tienen un registro… medir cuánto aprenden».',['Tiene 30.','Tiene 5.','Tiene 12.','Correcta.']),
q('REFLEXIONAR','Evaluar el sentido de un cierre','¿Qué destaca el contraste entre encender y no encender una lámpara?',['Que el éxito del encuentro depende de reparar todos los aparatos.','Que reconocer un riesgo también puede ser un resultado valioso.','Que las historias de objetos pendientes deben excluirse del informe.','Que el cable dañado demuestra la inutilidad de una revisión previa.'],'B','El cierre valora decidir cuándo no encender aún.',['No exige todos reparados.','Correcta.','Las fichas conservan pendientes.','Demuestra el valor de revisar.'])
]),
text('Discurso','Un escenario con más voces',[
 'Compañeras y compañeros del centro de estudiantes: hoy debemos decidir cómo se elegirán los números del encuentro artístico. El año pasado seleccionamos a quienes ya habían actuado en el colegio. El programa comenzó a tiempo y tuvo buena asistencia. Sin embargo, tres cursos no presentaron ningún número. Que la función resultara ordenada no significa que todos hayan tenido una oportunidad semejante de participar.',
 'Propongo abrir una convocatoria con criterios publicados y una instancia de ensayo para quienes nunca han subido al escenario. No propongo aceptar toda presentación sin revisarla. La duración, las condiciones técnicas y el respeto al público deben seguir siendo requisitos comunes. Lo que quiero cambiar es la idea de que la experiencia previa sea la entrada obligatoria a un espacio donde también se puede aprender.',
 'Una estudiante de primero contó que no postuló porque pensó que debía conocer al equipo organizador. No sabemos cuántas personas tuvieron la misma impresión; sería equivocado convertir su experiencia en una cifra general. Pero basta para revisar si nuestras instrucciones fueron claras. El cartel decía «Trae tu propuesta» y no indicaba dónde entregarla, cuánto podía durar ni quién respondería. Para alguien que no conocía la organización, la invitación quedaba incompleta.',
 'Algunos temen que recibir más propuestas haga imposible preparar la función. Esa preocupación tiene una respuesta práctica: un plazo único, una ficha breve y una comisión con representantes de distintos cursos. La comisión podrá seleccionar según los criterios conocidos, comunicar sus decisiones y ofrecer una explicación cuando una propuesta no quede en el programa. Abrir la convocatoria no nos obliga a borrar la capacidad del escenario.',
 'También debemos distinguir entre evaluar una presentación y decidir que una persona no tiene nada que aportar. Una propuesta puede necesitar cambios de duración o una solución técnica que no podemos ofrecer este año. Comunicar ese motivo permite buscar otra forma de participar. Decir simplemente «no quedaste» deja al estudiante sin saber qué revisar. El apoyo no garantiza que una propuesta sea seleccionada; sí puede evitar que la falta de información se confunda con falta de capacidad.',
 'Hay tareas fuera del escenario que también requieren participación: sonido, montaje, recepción y registro. La convocatoria debería explicar cómo integrarse a esos equipos. No lo propongo como destino obligatorio para quienes no actúen, sino como otra elección posible. Un encuentro abierto debe permitir conocer las opciones, no repartirlas según quién se atreve a preguntar primero.',
 'Quien ya tiene experiencia seguirá pudiendo participar. No se trata de castigar a quienes lo hicieron bien ni de presentar la novedad como un mérito suficiente. Se trata de permitir que la calidad de la propuesta se vea antes de descartarla por el nombre de quien la presenta. Si una función representa al colegio, ¿qué colegio estamos mostrando cuando siempre escuchamos las mismas voces?',
 'Les pido votar una convocatoria abierta, con criterios y apoyos claros. Antes de publicarla, probemos las instrucciones con una persona que no conozca al equipo: si puede decir dónde entregar, qué preparar y cuándo recibirá respuesta, estaremos más cerca de una invitación real. El encuentro seguirá necesitando orden. La diferencia es que ese orden podrá servir para que más personas encuentren su lugar, en vez de decidir de antemano quién lo tiene.'
],[
q('LOCALIZAR','Ubicar una evidencia explícita','¿Cuántos cursos no presentaron un número el año anterior?',['Tres cursos.','Un curso.','Dos cursos.','Cuatro cursos.'],'A','«tres cursos no presentaron ningún número».',['Correcta.','Confunde el testimonio con cursos.','No corresponde.','No corresponde.']),
q('LOCALIZAR','Discriminar propuestas','¿Qué apoyo se propone para quienes nunca han actuado?',['Una presentación sin límite de duración.','Un puesto asegurado en la comisión.','Una votación reservada a sus cursos.','Una instancia de ensayo antes del encuentro.'],'D','«una instancia de ensayo para quienes nunca han subido al escenario».',['Mantiene duración como criterio.','No garantiza puesto.','La votación es del centro.','Correcta.']),
q('INTERPRETAR','Determinar postura','¿Qué cambio defiende la persona que habla?',['Reemplazar las actuaciones antiguas por números nuevos sin selección.','Seleccionar propuestas con criterios claros y oportunidades de acceso.','Elegir artistas según la cantidad de público del año anterior.','Entregar la selección a quienes ya conocen al equipo organizador.'],'B','Convocatoria abierta, criterios comunes y apoyo a nuevos participantes.',['No acepta sin revisar ni castiga experiencia.','Correcta.','No selecciona por asistencia pasada.','Busca superar esa barrera.']),
q('INTERPRETAR','Relacionar una objeción y su respuesta','¿Cómo responde a quienes temen recibir demasiadas propuestas?',['Propone que cada curso elija sin considerar las condiciones técnicas.','Propone reservar la convocatoria a estudiantes con experiencia previa.','Propone plazos, una ficha y una comisión que aplique criterios conocidos.','Propone que toda presentación se realice aunque extienda la función.'],'C','Párrafo 4: plazo único, ficha breve y comisión.',['Mantiene condiciones técnicas.','Es la práctica cuestionada.','Correcta.','No borra capacidad del escenario.']),
q('REFLEXIONAR','Evaluar una pregunta retórica','¿Qué función cumple «¿qué colegio estamos mostrando…?»?',['Invita a cuestionar si el programa representa la diversidad del colegio.','Solicita identificar el nombre oficial del establecimiento ante el público.','Busca una cifra exacta de estudiantes que actuaron el año pasado.','Permite anunciar quiénes integrarán la comisión antes de la votación.'],'A','Cuestiona escuchar siempre las mismas voces al representar al colegio.',['Correcta.','Es reflexión sobre representación.','No solicita cifra.','No anuncia integrantes.']),
q('REFLEXIONAR','Evaluar el uso de un testimonio','¿Por qué se aclara que no se sabe cuántas personas pensaron como la estudiante?',['Para negar que la estudiante haya tenido dificultades para postular.','Para demostrar que los demás estudiantes entendieron las instrucciones.','Para excluir su relato de la discusión sobre cómo invitar al encuentro.','Para evitar generalizar una experiencia individual a todo el colegio.'],'D','«sería equivocado convertir su experiencia en una cifra general».',['Reconoce su dificultad.','No se conoce al resto.','Usa el relato para revisar instrucciones.','Correcta.'])
])
]);

exam('Leer entre líneas', ['Tiempo narrativo y retrospección','Intertextualidad y alusiones','Problema humano y estereotipos','Carta argumentativa','Tesis y suficiencia de argumentos','Ironía y contraste'], [
text('Cuento','El hilo en el bolsillo',[
 'Antes de entrar al edificio donde sería su entrevista, Marina encontró un carrete de hilo en el bolsillo. Lo había puesto su abuela esa mañana, mientras ella buscaba los documentos. «Para que vuelvas», había dicho. Marina sonrió: la oficina tenía cuatro pisos y un ascensor, no parecía un laberinto. Guardó el carrete por no discutir y salió hacia una ciudad donde las calles todavía le resultaban ajenas.',
 'En el ascensor recordó su primera semana en el pueblo de la abuela, ocho años antes. Se había perdido entre pasajes que parecían idénticos. La abuela la encontró frente a una panadería, furiosa consigo misma, y la llevó a casa sin preguntarle cómo pudo equivocarse. Esa noche le contó una historia: un joven había entrado en un laberinto y pudo regresar siguiendo el hilo que alguien le entregó. Marina preguntó por qué necesitaba ayuda alguien tan valiente. «Tal vez porque ser valiente no es conocer todos los caminos», respondió la abuela.',
 'La entrevista comenzó con una pregunta sobre su experiencia. Marina habló del taller donde había trabajado y del proyecto que ayudó a organizar. El hombre que la escuchaba miró su dirección en el formulario. «¿Vienes de allá? Debe de ser difícil adaptarse a un ritmo de verdad», comentó. Marina conocía ese tono: en el colegio de la ciudad ya lo había oído cuando alguien suponía que vivir lejos equivalía a saber menos. Bajó la vista al borde de la carpeta.',
 'Quiso enumerar cada premio y cada curso, demostrar que no estaba donde el hombre imaginaba. En cambio, pidió que le explicara qué ritmo exigía el cargo. Él señaló dos tareas y un plazo. Marina describió cómo había resuelto un trabajo semejante en el taller. Mientras hablaba, notó el carrete contra su mano. No necesitaba explicar toda su vida; necesitaba responder a lo que se le pedía sin aceptar la descripción que otro había hecho de ella.',
 'Al terminar, el entrevistador dijo que recibiría una respuesta durante la semana. Marina salió sin saber si la contratarían. En la calle, el tráfico le pareció más ruidoso que al llegar. Caminó hasta una plaza y llamó a su abuela. «¿Encontraste la salida?», preguntó la voz al otro lado. Marina dijo que todavía no sabía el resultado. «No te pregunté por el trabajo», respondió la abuela.',
 'Antes de cortar, la abuela preguntó si había almorzado. Marina miró una bolsa de pan que alguien había dejado sobre la banca y comenzó a reír. Había preparado tantas respuestas sobre su trayectoria que no llevaba ninguna para una pregunta tan simple. Dijo que buscaría un lugar cerca del terminal. Su abuela le recordó que guardara la boleta del pasaje. La conversación volvió a los encargos pequeños, aquellos que por la mañana le habían parecido propios de alguien incapaz de entender la importancia de una entrevista.',
 'Marina desenrolló un poco de hilo y lo dejó cruzar entre sus dedos. Pensó en el hombre, en el pasaje de la panadería y en la pregunta de aquella noche. Después guardó el carrete y buscó en el teléfono el camino al terminal. La ciudad seguía siendo desconocida, pero ya no le parecía necesario fingir que la conocía. Antes de levantarse de la banca envió un mensaje al antiguo taller: «Gracias por lo que aprendí allá». No mencionó la entrevista.'
],[
q('LOCALIZAR','Discriminar tiempos narrativos','¿Cuándo se perdió Marina cerca de la panadería?',['La mañana en que fue a la entrevista.','Ocho años antes, durante una visita al pueblo.','La semana posterior a recibir la respuesta laboral.','La tarde en que regresó al antiguo taller.'],'B','«su primera semana… ocho años antes».',['Confunde presente y recuerdo.','Correcta.','Aún no recibe respuesta.','No describe regreso al taller.']),
q('INTERPRETAR','Inferir un prejuicio','¿Qué supuesto se reconoce en el comentario del entrevistador?',['Que Marina necesita una recomendación de su abuela para trabajar.','Que todas las personas del taller desean cambiarse a la ciudad.','Que el cargo requiere viajar con frecuencia al pueblo de Marina.','Que venir de un lugar apartado implica menor capacidad de adaptación.'],'D','«adaptarse a un ritmo de verdad» y «vivir lejos equivalía a saber menos».',['No menciona recomendación.','Generalización no expresada.','No describe viajes del cargo.','Correcta.']),
q('INTERPRETAR','Relacionar una alusión literaria','¿Cómo se relaciona la historia del laberinto con la experiencia de Marina?',['Ambas vinculan la ayuda recibida con orientarse en una situación difícil.','Ambas muestran que seguir un hilo garantiza obtener lo que se busca.','Ambas presentan a alguien que conoce de antemano todos los caminos.','Ambas explican que la salida depende de vencer a un adversario físico.'],'A','El hilo y la enseñanza ayudan a afrontar una experiencia desconocida.',['Correcta.','No garantiza contratación.','Desconoce la ciudad y las tareas concretas.','No hay adversario físico.']),
q('INTERPRETAR','Inferir una decisión','¿Por qué Marina pregunta por las tareas del cargo?',['Busca evitar hablar de su trabajo en el taller.','Quiere demostrar que ya conoce el edificio de la empresa.','Decide responder desde su experiencia y cuestionar el supuesto recibido.','Pretende aplazar la entrevista hasta que llegue su abuela.'],'C','Pregunta el ritmo/tareas y describe cómo resolvió un trabajo semejante.',['Sí habla de su experiencia.','El edificio no es el tema.','Correcta.','No busca aplazar.']),
q('INTERPRETAR','Determinar un problema humano','¿Qué problema humano se desarrolla principalmente?',['La dificultad de recordar instrucciones técnicas antiguas.','La búsqueda de reconocimiento frente a una mirada prejuiciosa.','La obligación de elegir entre una familia y un empleo.','La rivalidad entre trabajadores de un mismo taller.'],'B','Marina enfrenta una descripción que reduce su capacidad por su origen.',['No olvida las tareas.','Correcta.','No se exige separarse de familia.','No hay rivalidad laboral.']),
q('REFLEXIONAR','Evaluar una retrospección','¿Qué aporta el recuerdo de la panadería a la narración?',['Revela el motivo económico de la mudanza a la ciudad.','Anticipa el resultado de la entrevista de trabajo.','Demuestra que la abuela conoce al entrevistador.','Permite comprender el sentido del hilo y la ayuda de la abuela.'],'D','En el recuerdo se cuenta el laberinto y el significado de recibir ayuda.',['No explica economía.','El resultado queda abierto.','No se conocen.','Correcta.'])
]),
text('Carta al director','Cuando el horario no basta',[
 'Señora directora: su periódico informó que el nuevo consultorio extendió la atención hasta las siete de la tarde. La medida puede facilitar el acceso de quienes trabajan durante el día. Sin embargo, creo que evaluar ese acceso requiere mirar también cómo llegan y cómo regresan las personas. Un horario más amplio pierde parte de su utilidad si el transporte deja de funcionar antes de que termine la atención.',
 'Mi padre acudió el jueves a un control agendado para las seis. La última micro hacia nuestro sector sale del centro a las seis y media. El control terminó a las seis y cuarenta y él volvió en un vehículo particular que pudo pagar gracias a un familiar. No afirmo que a todos les ocurra lo mismo. El consultorio atiende sectores con recorridos distintos. Su experiencia muestra una pregunta que no aparece en el anuncio del nuevo horario: ¿se consideraron los trayectos de quienes usarán las horas añadidas?',
 'Algunas personas responderán que el consultorio no administra las micros. Es cierto. No le pido que cambie por sí solo una ruta de transporte. Propongo que, al ofrecer las horas de la tarde, se informe sobre los recorridos disponibles y que se consulte a los usuarios por sus dificultades de regreso. Esa información permitiría conversar con quienes organizan el transporte y distinguir un problema ocasional de una barrera repetida.',
 'Otra solución sería reservar los controles tardíos para quienes viven cerca. Puede parecer eficiente, pero dejaría fuera a personas que precisamente necesitan ese horario por su trabajo. La cercanía no debería convertirse en una condición automática. Sería mejor preguntar por la posibilidad de regreso antes de asignar la hora y ofrecer alternativas cuando exista una dificultad, sin obligar al usuario a explicar toda su vida en el mesón.',
 'La consulta podría realizarse al entregar la hora y repetirse después de la atención. No todas las dificultades serán iguales: una persona puede depender de un recorrido, otra de quien la acompaña y otra de un horario laboral que cambia cada semana. Preguntar no significa prometer una solución inmediata para cada situación. Permite saber qué problema se está intentando resolver antes de diseñar una respuesta. Sin ese registro, una hora que queda vacía podría interpretarse como desinterés del usuario, aunque haya sido ofrecida bajo condiciones que no le permitían llegar o regresar sin una dificultad importante.',
 'El anuncio del consultorio incluyó un mapa con su ubicación y una lista de prestaciones. Ambos recursos son útiles, pero no explican cómo se conectan los distintos sectores con esa dirección después de las seis. Un mapa permite localizar un punto; no garantiza que una persona pueda alcanzarlo y regresar a su casa. Añadir información sobre transporte no reemplaza la atención de salud, pero ayuda a que el horario ampliado sea efectivamente aprovechable.',
 'Solicito que el periódico consulte a la administración cómo se evaluará el uso de las nuevas horas y si recogerá las dificultades de traslado. No escribo para que se elimine la extensión. La valoro y quiero que alcance a quienes más podrían beneficiarse. Abrir una puerta es un paso; averiguar si las personas pueden llegar hasta ella permite saber cuánto cambió realmente su acceso. Atentamente, una lectora del sector Las Canteras.'
],[
q('LOCALIZAR','Ubicar horarios y distinguirlos','¿A qué hora sale la última micro hacia el sector de la autora?',['A las seis de la tarde.','A las seis y cuarenta.','A las seis y media.','A las siete de la tarde.'],'C','«La última micro… sale… a las seis y media».',['Es la hora del control.','Es cuando termina el control.','Correcta.','Es el cierre del consultorio.']),
q('INTERPRETAR','Determinar propósito comunicativo','¿Qué busca principalmente la carta?',['Suprimir las horas de la tarde para evitar viajes particulares.','Mejorar el acceso al horario ampliado considerando el transporte.','Responsabilizar al periódico de organizar las rutas del barrio.','Reservar todos los controles tardíos para los usuarios cercanos.'],'B','Valora extensión y solicita consultar cómo evaluar dificultades de traslado.',['Rechaza eliminarla.','Correcta.','Pide que consulte, no que organice rutas.','Cuestiona esa reserva automática.']),
q('INTERPRETAR','Relacionar argumento y evidencia','¿Qué demuestra el caso del padre dentro del argumento?',['Que un horario disponible puede resultar difícil de usar por el regreso.','Que todos los pacientes del consultorio dependen de la misma micro.','Que el control fue retrasado por una falla del personal de salud.','Que el vehículo particular es la alternativa más económica del sector.'],'A','La atención termina después de salir la última micro de ese sector.',['Correcta.','La autora aclara recorridos distintos.','No explica retraso ni falla.','No compara costos.']),
q('REFLEXIONAR','Evaluar una objeción','¿Por qué se reconoce que el consultorio no administra las micros?',['Para concluir que los usuarios deben resolver el problema sin apoyo.','Para retirar la petición de consultar dificultades de traslado.','Para justificar que el horario se limite a quienes llegan caminando.','Para delimitar la responsabilidad y proponer una acción posible.'],'D','Reconoce límite y propone informar, consultar y conversar con transporte.',['Sigue solicitando apoyo.','Mantiene la petición.','Rechaza condición por cercanía.','Correcta.']),
q('INTERPRETAR','Interpretar una analogía','¿Qué significa «abrir una puerta» en el cierre?',['Publicar un mapa nuevo con los recorridos del barrio.','Instalar una entrada adicional para evitar esperas.','Ofrecer una posibilidad de atención que debe volverse accesible.','Permitir que el transporte ingrese al patio del consultorio.'],'C','La puerta representa horario ampliado; llegar implica acceso real.',['El mapa es un recurso, no el significado central.','Literaliza.','Correcta.','No se propone ingreso de transporte.']),
q('REFLEXIONAR','Evaluar la suficiencia de un recurso','¿Qué límite del mapa identifica la autora?',['Muestra la ubicación, pero no asegura transporte en los horarios necesarios.','Presenta una dirección distinta de la que tiene el nuevo consultorio.','Describe las prestaciones, pero omite el nombre de los profesionales.','Permite viajar por la mañana, pero impide circular después de las seis.'],'A','«localizar un punto; no garantiza… alcanzarlo y regresar».',['Correcta.','No se cuestiona exactitud de dirección.','Cambia el recurso: lista de prestaciones.','El mapa no permite ni impide circular.'])
]),
text('Ensayo breve','La eficacia de llegar a ninguna parte',[
 'La nueva aplicación de lectura del instituto promete eficiencia. Mide los minutos que cada estudiante mantiene un libro abierto y entrega una medalla digital al superar una meta. En la presentación, el desarrollador mostró un tablero lleno de barras verdes. No había fragmentos comentados ni preguntas sobre los libros. Según el tablero, un lector que sostuviera un libro abierto una hora sin entenderlo habría avanzado más que otro que leyera diez minutos y lograra explicar una idea difícil.',
 'La propuesta permite registrar un dato útil: el tiempo disponible para leer. Ese dato puede ayudar a conocer hábitos, siempre que no se confunda con la comprensión. Mi objeción comienza cuando una medida visible reemplaza el propósito de la actividad. Si el objetivo es comprender, la pregunta no termina al contar minutos. También importa qué relaciones puede establecer el lector, qué dudas reconoce y cómo justifica lo que entendió.',
 'Imaginemos una escuela de cocina que premiara a quien mantiene una olla más tiempo sobre el fuego. Sus estudiantes podrían graduarse con sopas evaporadas y una notable disciplina de espera. El ejemplo parece exagerado, pero permite separar el tiempo invertido del resultado buscado. Cocinar necesita tiempo; medirlo no basta para saber si la comida está bien preparada. Leer también necesita dedicación; la duración, por sí sola, no informa todo el aprendizaje.',
 'Una profesora propone combinar el registro con una conversación breve sobre lo leído. Su idea no exige examinar cada página ni poner nota a todos los comentarios. Busca que la información del tablero dialogue con una evidencia de comprensión. Un estudiante que lee lentamente podría mostrar una interpretación valiosa; otro que acumula minutos podría necesitar ayuda. Sin esa segunda mirada, el premio corre el riesgo de ocultar la necesidad de apoyo.',
 'Podría objetarse que explicar una idea también depende de la facilidad para hablar. La profesora no ignora esa diferencia: admite una nota breve, una conversación individual o el señalamiento de un pasaje acompañado de una explicación. Lo que necesita conocer no es quién habla con mayor soltura, sino qué relación puede establecer con lo leído. Esa variedad exige revisar con cuidado la evidencia, pero evita que cambiar un contador por una conversación signifique reemplazar una barrera por otra. Una herramienta debería ampliar lo que podemos observar del aprendizaje, no limitarlo a la forma de respuesta más cómoda para quien recoge los datos.',
 'Conviene reconocer una dificultad: escuchar a los lectores ocupa tiempo docente y no cabe con facilidad en una barra de colores. Sin embargo, que algo sea difícil de registrar no lo vuelve menos importante. El tablero puede ser una herramienta para organizar preguntas, en vez de convertirse en una respuesta automática. La misma tecnología que hoy entrega una medalla podría ayudar a guardar dudas y a recordar una conversación pendiente.',
 'No propongo abandonar el registro. Propongo bajarlo del podio. Al terminar una jornada, tal vez tengamos menos cifras que anunciar y más ideas que discutir. Sería una pérdida para quien confunde el aprendizaje con una vitrina llena de indicadores; para los lectores, podría ser un avance. La eficiencia merece una pregunta previa: ¿eficiencia para alcanzar qué? Si olvidamos el destino, llegar más rápido solo nos permite extraviarnos antes.'
],[
q('LOCALIZAR','Ubicar un criterio explícito','¿Qué dato usa la aplicación para entregar una medalla?',['Los fragmentos que el lector comenta.','Las preguntas que formula sobre el libro.','Las ideas que explica en una conversación.','Los minutos que mantiene abierto un libro.'],'D','«Mide los minutos… un libro abierto y entrega una medalla».',['No aparecen fragmentos en tablero.','No usa preguntas.','Es propuesta de la profesora.','Correcta.']),
q('LOCALIZAR','Discriminar propuestas','¿Qué propone añadir la profesora al registro?',['Una segunda medalla por velocidad.','Una conversación breve sobre lo leído.','Una nota obligatoria por cada página.','Una lista de libros ordenada por extensión.'],'B','«combinar el registro con una conversación breve».',['No agrega premio de velocidad.','Correcta.','No exige examinar cada página.','No propone esa lista.']),
q('INTERPRETAR','Determinar tesis','¿Qué idea defiende el ensayo?',['La lectura lenta demuestra una comprensión inferior a la rápida.','Las aplicaciones impiden conversar sobre cualquier lectura.','El tiempo es un dato útil que no debe reemplazar la evidencia de comprensión.','Las medallas permiten interpretar de manera suficiente un libro.'],'C','Reconoce utilidad del dato y pide combinarlo con evidencia de comprensión.',['Un lector lento puede interpretar bien.','Propone usar tecnología para guardar dudas.','Correcta.','Critica esa sustitución.']),
q('INTERPRETAR','Interpretar ironía','¿Qué sugiere la expresión «una notable disciplina de espera»?',['Cuestiona con humor un premio que ignora el resultado de cocinar.','Recomienda extender la cocción para mejorar todas las preparaciones.','Describe una habilidad que la escuela de cocina mide de forma oficial.','Explica que esperar es una tarea más compleja que comprender.'],'A','Sopas evaporadas contrastadas con premio por tiempo.',['Correcta.','La consecuencia es negativa.','El ejemplo es imaginado.','No jerarquiza dificultad.']),
q('REFLEXIONAR','Evaluar y comparar dos textos','¿Qué comparación entre «El hilo en el bolsillo» y «La eficacia de llegar a ninguna parte» está mejor sustentada?',['Ambos presentan la experiencia en un taller como evidencia de aprendizaje.','Ambos proponen acompañar el registro de tiempo con conversaciones sobre lo aprendido.','Ambos muestran que llegar a una ciudad desconocida puede provocar inseguridad.','Ambos cuestionan juzgar capacidades con indicadores que no permiten demostrarlas.'],'D','Cuento: «vivir lejos equivalía a saber menos» y respuesta desde su experiencia. Ensayo: minutos sin comprensión, frente a explicación de una idea.',['La experiencia en el taller pertenece al cuento.','La propuesta de registro y conversación pertenece al ensayo.','La ciudad desconocida pertenece al cuento.','Correcta: en ambos, un indicador insuficiente reemplaza una evidencia de capacidad.']),
q('REFLEXIONAR','Evaluar una interpretación global','¿Qué afirmación interpreta mejor «Propongo bajarlo del podio»?',['Eliminar todo dato sobre hábitos de lectura para evitar comparaciones.','Usar el registro como apoyo y dejar de tratarlo como prueba suficiente.','Reservar las medallas para quienes expliquen todas las páginas del libro.','Cambiar el registro digital por un contador manual de minutos.'],'B','«No propongo abandonar el registro»; herramienta para organizar preguntas.',['Expresamente conserva registro.','Correcta.','No establece nuevas medallas.','El soporte no es el problema.'])
])
]);

exam('Integrar, interpretar y evaluar', ['Tema y sentido global','Símbolos y contraste','Texto informativo y secuencia','Relación texto-diagrama','Publicidad y propaganda','Evidencia y generalizaciones'], [
text('Poema','El puente y la orilla',[
 'El río pasa debajo\nsin leer el nombre del puente.\nLa placa dice quién lo hizo;\nel agua no se detiene.\nSobre la baranda un niño\nsuelta una hoja corriente.',
 'De esta orilla sale un carro,\nde aquella vuelve una mujer.\nLos pasos cruzan sus sombras,\nninguno pregunta por qué.\nEl puente aprende caminos\nque no trazó quien lo hizo.',
 'Ayer el viento dejó\nuna rama entre las tablas.\nUn hombre vino a quitarla\ncon las manos ya cansadas.\nSu nombre no está en la placa;\nsu trabajo abre la mañana.',
 'Yo esperaba un monumento,\nun lugar para mirar.\nEncontré bolsas de harina,\nuna rueda que reparar,\nla conversación de dos vecinos\nque no se podían visitar.',
 'El niño sigue a la hoja\ncon los ojos desde arriba.\nLa hoja gira y se aleja,\nel puente permanece.\nNo todo lo que se mueve se pierde;\nno todo lo que se queda sostiene.',
 'Cuando oscurece, regreso.\nLlevo la otra orilla en los zapatos.\nEl agua borra mis reflejos\ny el puente devuelve mis pasos.\nMañana alguien cruzará primero:\nquizás quien vino a limpiarlo.'
],[
q('LOCALIZAR','Ubicar una acción explícita','¿Qué retira el hombre de las tablas del puente?',['Una placa con el nombre del constructor.','Una bolsa de harina que dejó un vecino.','Una hoja que soltó el niño desde arriba.','Una rama que había dejado el viento.'],'D','«el viento dejó / una rama… Un hombre vino a quitarla».',['No retira la placa.','La harina pertenece a usuarios.','La hoja flota en río.','Correcta.']),
q('INTERPRETAR','Interpretar una personificación','¿Qué sugiere que el puente «aprende caminos»?',['Que el constructor modifica su diseño después de inaugurarlo.','Que su sentido se amplía con los recorridos de quienes lo usan.','Que el río cambia de dirección al encontrar la estructura.','Que el niño memoriza las rutas que recorren los vecinos.'],'B','Los pasos y usos exceden lo que trazó quien lo hizo.',['No se cambia diseño.','Correcta.','No cambia río.','Sujeto y sentido no son el niño.']),
q('INTERPRETAR','Inferir la postura del hablante','¿Qué descubre el hablante frente a su expectativa inicial?',['Que el puente vale también por el uso cotidiano y el cuidado que recibe.','Que la placa permite reconocer a todas las personas que mantienen el puente.','Que observar el río es la única actividad posible desde sus barandas.','Que los vecinos dejaron de visitar la otra orilla después de construirlo.'],'A','Esperaba monumento, encuentra harina, rueda, conversación y cuidado.',['Correcta.','El trabajador no está en placa.','Ve usos variados.','Ahora se pueden visitar.']),
q('INTERPRETAR','Determinar tema global','¿Qué tema relaciona las escenas del poema?',['La necesidad de levantar un monumento a quienes viajan por el río.','La competencia entre ambas orillas por controlar el paso de los carros.','El valor de una obra compartida que conecta vidas y requiere cuidado.','El deseo del niño de recuperar una hoja que se llevó la corriente.'],'C','Cruces, conexión de vecinos y mantenimiento anónimo.',['No propone nuevo monumento.','No hay competencia.','Correcta.','No intenta recuperar hoja.']),
q('INTERPRETAR','Interpretar lenguaje figurado','¿Qué expresa «Llevo la otra orilla en los zapatos»?',['Que el hablante carga una parte del puente para repararlo.','Que sus zapatos fueron fabricados al otro lado del río.','Que el río arrastró los zapatos durante el viaje de regreso.','Que el encuentro con el otro lado deja una huella en su regreso.'],'D','Regresa después de observar usos y personas del otro lado.',['Literaliza como carga.','No habla de fabricación.','Sigue caminando con zapatos.','Correcta.']),
q('REFLEXIONAR','Evaluar un contraste','¿Qué aporta el contraste entre la placa y el hombre que limpia?',['Destaca una contribución cotidiana que no recibe el reconocimiento de la placa.','Demuestra que el constructor abandonó una obra antes de terminarla.','Explica por qué el niño suelta una hoja sin consultar a los adultos.','Establece que quitar la rama es más difícil que construir el puente.'],'A','«Su nombre no está en la placa; / su trabajo abre la mañana».',['Correcta.','No relata abandono.','No explica esa acción.','No compara dificultad.'])
]),
text('Artículo informativo con diagrama','Una semilla no viaja sola',[
 'Una semilla puede alejarse de la planta que la produjo de distintas maneras. Algunas tienen estructuras que facilitan su transporte por el viento; otras quedan adheridas al pelaje de un animal o viajan dentro de un fruto. Esa dispersión cambia el lugar donde la semilla puede germinar. No garantiza, sin embargo, que de cada semilla transportada crezca una nueva planta: el lugar de llegada también importa.',
 'En la dispersión mediante frutos intervienen varias etapas. Un animal come el fruto y puede desplazarse antes de expulsar las semillas. Si estas conservan su capacidad de germinar y llegan a un sitio con condiciones apropiadas, podrían desarrollarse. El diagrama resume ese recorrido. Sus flechas indican una secuencia posible, no una promesa de éxito en cada paso. Una semilla puede dañarse o caer sobre una superficie donde no encuentre agua suficiente.',
 'Para observar una parte del proceso, un curso instaló dos bandejas con la misma cantidad de semillas del mismo tipo. La bandeja A contenía suelo húmedo; la B, suelo seco. Ambas recibieron luz semejante y se mantuvieron en la misma sala. Durante diez días el curso anotó cuántas semillas mostraban un brote. Al final observó más brotes en A. Esa experiencia sugiere que, en las condiciones ensayadas, la humedad favoreció la germinación.',
 'El resultado no permite concluir que el suelo húmedo será suficiente para todas las especies ni que una semilla germinará en cualquier temperatura. El ensayo mantuvo algunas condiciones semejantes y modificó una de ellas; no exploró todas las combinaciones posibles. Repetirlo con nuevas semillas del mismo tipo ayudaría a revisar si el resultado se mantiene. Probar otra especie respondería una pregunta diferente y debería identificarse como tal.',
 'Al preparar su informe, el curso discutió si incluir fotografías del primer o del último día. Eligió mostrar ambas y anotar cuándo habían sido tomadas. Una imagen final de cada bandeja permitía comparar brotes, pero no mostraba la condición inicial del ensayo. El grupo conservó además sus anotaciones diarias, incluyendo las semillas que todavía no habían cambiado. Esos registros podrían resultar útiles si otra persona quisiera repetir la experiencia. Una fotografía llamativa puede orientar la atención hacia un resultado; acompañarla con fechas y condiciones permite comprender mejor de qué observación proviene y qué comparación está haciendo el informe.',
 'Cuando se describe a los animales como «transportistas», se usa una comparación para explicar su papel en la dispersión. No significa que el animal conozca el destino ni que busque cultivar una planta. La función surge de acciones como alimentarse y desplazarse. Una misma acción puede tener consecuencias para otros organismos sin haber sido realizada con esa intención. Separar función e intención permite leer la explicación sin atribuir decisiones humanas al animal.',
 'Comprender el recorrido requiere mirar tanto el transporte como las condiciones de llegada. Una observación de semillas lejos de la planta de origen puede orientar una investigación, pero no permite saber por sí sola qué animal las llevó. Harían falta otras evidencias. Del mismo modo, encontrar un brote informa que hubo germinación; no demuestra que esa planta llegue a adulta. Cada etapa abre una posibilidad y plantea una pregunta que la siguiente observación debe precisar.'
],[
q('LOCALIZAR','Discriminar variables','¿Qué condición fue diferente entre las bandejas A y B?',['La cantidad inicial de semillas.','La humedad del suelo utilizado.','El tipo de semilla que se colocó.','La sala donde recibieron la luz.'],'B','A: suelo húmedo; B: suelo seco; cantidad, tipo y sala semejantes.',['Misma cantidad.','Correcta.','Mismo tipo.','Misma sala.']),
q('INTERPRETAR','Integrar una secuencia','¿Qué relación muestra el diagrama?',['La comparación entre los brotes de las bandejas A y B.','La identificación del animal que transportó una semilla encontrada.','Una secuencia posible desde el consumo del fruto hasta la germinación.','Una lista de animales ordenada según cuánto alimento consumen.'],'C','Fruto → consumo → desplazamiento/expulsión → llegada apropiada → germinación posible.',['El diagrama no presenta bandejas.','No identifica especie animal.','Correcta.','No ordena animales.']),
q('INTERPRETAR','Interpretar una expresión','¿Qué significa llamar «transportistas» a los animales?',['Que sus acciones pueden desplazar semillas sin una intención de cultivarlas.','Que seleccionan el suelo adecuado antes de depositar cada semilla.','Que buscan reproducir las plantas que les darán alimento en el futuro.','Que conocen las etapas que garantizan el crecimiento de una planta.'],'A','Se alimentan/desplazan; no conocen destino ni buscan cultivar.',['Correcta.','Atribuye selección deliberada.','Atribuye intención no descrita.','El proceso no garantiza crecimiento.']),
q('REFLEXIONAR','Evaluar un procedimiento','¿Para qué se mantuvieron semejantes la luz y el tipo de semillas?',['Para asegurar que todas las semillas de ambas bandejas germinaran.','Para demostrar que la humedad no influye en la aparición de brotes.','Para reproducir las condiciones de todas las especies de plantas.','Para observar la diferencia de humedad con menos factores en competencia.'],'D','Se mantuvieron condiciones semejantes y se modificó humedad.',['No garantiza germinación.','El resultado sugiere influencia.','Usa un mismo tipo.','Correcta.']),
q('INTERPRETAR','Distinguir etapas y consecuencias','¿Por qué encontrar un brote no prueba que habrá una planta adulta?',['Porque los brotes solo aparecen en suelos secos.','Porque la germinación es una etapa y el desarrollo posterior no está asegurado.','Porque el brote permite identificar al animal que llevó la semilla.','Porque las semillas de los frutos no conservan capacidad de germinar.'],'B','«informa que hubo germinación; no demuestra… llegue a adulta».',['Contradice observación.','Correcta.','No identifica animal.','Algunas conservan capacidad.']),
q('REFLEXIONAR','Evaluar alcance de una conclusión','¿Qué conclusión es compatible con la experiencia de las bandejas?',['La humedad fue suficiente para producir plantas adultas en diez días.','Las semillas de cualquier especie germinan mejor con la misma cantidad de agua.','En las condiciones ensayadas, el suelo húmedo presentó más brotes.','Los animales distribuyen las semillas hacia suelos donde hay más luz.'],'C','Resultado local: más brotes A, con semillas del mismo tipo.',['Solo observó brotes.','Generaliza a todas especies.','Correcta.','No estudió conducta animal.'])
],{headers:['Etapa','Qué ocurre'],rows:[['1','Un animal come un fruto.'],['2','Se desplaza y expulsa semillas.'],['3','Algunas semillas llegan a un lugar apropiado.'],['4','Si conservan su capacidad y hay condiciones adecuadas, pueden germinar.']],caption:'Recorrido posible: 1 → 2 → 3 → 4. Cada paso depende de condiciones; no asegura el siguiente.'}),
text('Afiche de campaña y comentario','La reparación empieza antes de botar',[
 'AFICHE DE CAMPAÑA\n«¿Un cierre roto? No cierres la posibilidad de repararlo».\nJornada de reparación de mochilas y bolsos. Sábado 7, de 10:00 a 13:00, en la sede vecinal. Revisión gratuita; los repuestos no están incluidos. Trae tu objeto limpio. Se atenderán doce casos por orden de llegada. Organiza: Agrupación Manos del Barrio.',
 'IMAGEN DEL AFICHE\nDos dibujos del mismo bolso: en el primero, un cierre abierto y una flecha hacia un contenedor; en el segundo, una mano cose junto al cierre y una flecha conduce hacia una persona que usa el bolso. Entre ambos dibujos aparece la pregunta «¿Todavía puede servir?». El contenedor no está tachado: debajo se lee «Si no es reparable, consulta cómo disponer sus materiales».',
 'PUBLICACIÓN DE LA AGRUPACIÓN\n«Este mes recibiremos mochilas y bolsos de tela. En encuentros anteriores algunas personas recuperaron objetos que ya habían dejado de usar. Otros necesitaron materiales que no teníamos disponibles. Por eso anotaremos el estado de cada caso antes de comenzar. Si tienes dudas sobre qué traer, pregunta por mensaje hasta el viernes. La sede queda a dos cuadras del terminal; no contamos con traslado de objetos ni retiro a domicilio».',
 'COMENTARIOS EN LA PUBLICACIÓN\nVecino 1: «Una vecina arregló su mochila; esta jornada resolverá el problema de la basura del barrio».\nVecina 2: «Si los repuestos no están incluidos, la revisión gratuita es una mentira».\nVecino 3: «Tengo un bolso con la tela gastada junto al cierre. ¿Pueden revisarlo o necesitan que lleve un repuesto?».\nVecina 4: «Fui el mes pasado con mi mochila. Me indicaron el material que faltaba y volví otro día con él».',
 'RESPUESTA DE LA AGRUPACIÓN\n«Podemos revisar la tela y el cierre durante la jornada. Si hacen falta materiales, los anotaremos en la ficha antes de intervenir. Quien lo prefiera podrá llevarse el objeto con esa información. No pedimos que compre algo sin conocer primero lo que necesita. Si los doce lugares están ocupados cuando lleguen, dejaremos anotado su contacto para avisar de la próxima fecha; no podemos sumar reparaciones fuera del horario porque la sala se usa después para otra actividad».',
 'MENSAJE DE CIERRE\n«El sábado pondremos una mesa junto a la entrada para recibir los objetos y explicar la ficha. Habrá muestras de costuras que se pueden practicar con retazos, aunque el bolso no alcance a atenderse ese día. Invitamos a quienes sepan reparar a conversar con el equipo sobre próximas jornadas. Una vecina llevará fotografías del arreglo de su mochila. Si tienen experiencias para compartir, pueden traerlas impresas o mostrarlas al comienzo. Para consultar por otros materiales, les daremos el contacto del punto de recepción del sector».'
 ,'AVISO DE LA SEDE\n«La sala se abrirá media hora antes para que el equipo prepare las mesas. Ese tiempo no corresponde a la atención de público. Al finalizar la jornada, cada participante debe retirar su objeto: no contamos con espacio para guardarlo hasta la próxima fecha. Quienes acompañen a otra persona podrán esperar en el patio. Si llueve, usaremos el pasillo cubierto, manteniendo libre el acceso a las otras salas. El afiche estará también en la puerta del almacén, donde algunas personas han pedido una copia porque no utilizan redes sociales».'
],[
q('LOCALIZAR','Discriminar una condición','¿Qué servicio se anuncia como gratuito?',['La revisión del objeto que se lleva.','La compra de todos los repuestos.','El traslado hasta la sede vecinal.','La entrega de un bolso de reemplazo.'],'A','«Revisión gratuita; los repuestos no están incluidos».',['Correcta.','Se excluyen.','No se ofrece traslado.','No se entrega bolso nuevo.']),
q('LOCALIZAR','Ubicar un límite explícito','¿Cuántos casos se atenderán según el afiche?',['Siete casos.','Diez casos.','Trece casos.','Doce casos.'],'D','«Se atenderán doce casos por orden de llegada».',['Es el día.','Es hora inicial.','Es hora final.','Correcta.']),
q('INTERPRETAR','Inferir destinatario','¿A quién se dirige principalmente la invitación?',['A quienes buscan comprar bolsos nuevos para venderlos después.','A quienes tienen un bolso dañado y quieren evaluar si puede repararse.','A quienes necesitan desechar todo tipo de residuos del barrio.','A quienes pueden ofrecer repuestos gratuitos a todos los asistentes.'],'B','Jornada revisión mochilas/bolsos, traer objeto limpio.',['No hay venta.','Correcta.','No incluye todos residuos.','No convoca donantes de repuestos.']),
q('INTERPRETAR','Determinar propósito e integrar recursos','¿Qué propósito comparten la pregunta y los dibujos del afiche?',['Asegurar que cada bolso podrá quedar en el mismo estado que uno nuevo.','Promover la compra de repuestos aunque el objeto no tenga arreglo.','Invitar a considerar la reparación antes de decidir desechar.','Mostrar que usar el contenedor está prohibido durante la jornada.'],'C','Dos posibles destinos y «¿Todavía puede servir?»; contenedor no tachado.',['No asegura reparación.','Invita revisar, no compra indiscriminada.','Correcta.','No prohíbe disponer materiales.']),
q('REFLEXIONAR','Identificar una generalización','¿Qué problema tiene el comentario sobre «resolver la basura del barrio»?',['Presenta una experiencia aislada como prueba de una solución general.','Confunde el horario de inicio con el plazo de devolución de los objetos.','Repite una cifra sobre residuos que el afiche demuestra con una tabla.','Cuestiona que la jornada incluya revisión de mochilas y bolsos.'],'A','Una vecina arregló mochila; no hay datos para problema general de residuos.',['Correcta.','No habla de horario.','No existe tabla de residuos.','No cuestiona alcance de objetos.']),
q('REFLEXIONAR','Evaluar una acusación según evidencia','¿Qué respuesta está mejor respaldada frente al comentario que acusa una mentira?',['El anuncio prueba que los repuestos serán gratuitos para los primeros doce.','El costo de repuestos demuestra que no habrá ninguna revisión gratuita.','La crítica permite concluir que organizar jornadas de reparación es inútil.','El anuncio distingue revisión gratuita de repuestos que no están incluidos.'],'D','Condición explícita del afiche.',['No establece esa gratuidad.','Confunde revisión y repuestos.','Generaliza una crítica particular.','Correcta.'])
])
]);

// Reordenación editorial posterior a fijar la evidencia, sin cambiar opciones.
require('./_simce-u4-literature').apply(exams,{text,q});
exams.forEach(exam=>{let i=0;exam.texts.forEach(t=>t.questions.forEach(q=>{q.id=`q${++i}`;}));});
require('./_simce-u4-demand').apply(exams);
require('./_simce-u4-writing').apply(exams);
// 4/5 claves por letra, sin ciclos de dos/cuatro ni tres claves consecutivas.
const keyOrders=['CBADCDCCBBDABABDAD','CDACACDCBBDBDBBADA','DBCACDBBADBBDACDAC','ADDCDDCBBCBDACBAAB','DAACCBDDBBADCCADBB'];
exams.forEach((exam,index)=>exam.texts.flatMap(t=>t.questions).forEach((item,i)=>{
  const offset=('ABCD'.indexOf(item.key)-'ABCD'.indexOf(keyOrders[index][i])+4)%4;
  item.options=item.options.slice(offset).concat(item.options.slice(0,offset));
  item.errors=item.errors.slice(offset).concat(item.errors.slice(0,offset));
  item.key=keyOrders[index][i];
}));
function publicExam(number) {
  const value = exams[number - 1];
  if (!value) return null;
  return { number:value.number, sessionId:value.sessionId, date:value.date, title:value.title,
    texts:value.texts.map(t => ({ title:t.title, genre:t.genre, paragraphs:t.paragraphs, source:t.source,
      ...(t.table ? {table:t.table} : {}), questions:t.questions.map(q => ({id:q.id,prompt:q.prompt,options:q.options})) })) };
}
module.exports = { exams, dates, publicExam };
